from typing import Dict, Any

def get_cung_dau_dich_nu_tuong_mon_masterpiece_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Đích Nữ Tướng Môn: Nhận Chiếu Hòa Thân, Nàng San Bằng Biên Cương Về Triều"
    part1_full = "Quan tài gỗ trầm của phụ thân tôi – vị đại tướng quân trấn giữ biên thùy ba mươi năm – còn chưa kịp hạ huyệt, tổng quản nội đình đã mang thánh chỉ ép gả hòa thân bước vào đại sảnh phủ Định Quốc Công. Tấm thánh chỉ màu vàng rực được nội quan tổng quản bưng vào sảnh đường phủ Định Quốc Công giữa một buổi sáng mưa dầm buốt giá. Cha tôi – vị đại tướng quân trấn giữ biên cương ba mươi năm vừa hy sinh ngoài sa trường chưa đầy ba mươi ngày, mảnh khăn tang trên đầu tôi vẫn còn trắng xóa.\n\nTiếng mưa rơi lộp độp trên mái ngói sảnh đường như từng tiếng khóc than ai oán cho mười vạn quân dân biên thùy vừa ngã xuống. Vị nội quan họ Cao vuốt chòm râu dê mỏng dính, khinh khỉnh mở rộng chiếu thư bọc gấm vàng, giọng the thé lanh lảnh vang khắp sảnh lớn:\n'Phụng thiên thừa vận hoàng đế chiếu viết: Phủ Định Quốc Công đời đời trung liệt, nay tướng quân tử trận, giặc Bắc Địch đòi hòa thân mới chịu rút quân khỏi biên ải. Triều đình xét thấy đích nữ Tần Uyển Dao đoan trang đức hạnh, đặc ban phong làm Chiêu Hòa Công chúa, ba ngày sau theo sứ đoàn lên đường gả sang thảo nguyên Bắc Địch để cứu vãn giang sơn xã tắc. Khâm thử!'.\n\nTừng chữ trong cuốn chiếu thư như những lưỡi dao sắc lẹm đâm thẳng vào tim mẹ tôi. Bà nghẹn ngào thốt lên một tiếng rồi ngất lịm ngay trên ghế gụ bọc nhung. Ba người thúc phụ từng cùng cha tôi xông pha trận mạc đứng phía sau siết chặt chuôi kiếm đến mức khớp xương kêu răng rắc, ánh mắt họ bốc hỏa hận thù.\n\nAi trong kinh thành này mà không biết Bắc Địch là vùng đất man rợ ngoài quan ải? Thủ lĩnh của chúng – Hãn vương Ô Lặc Đạt – đã ngoài sáu mươi tuổi, tính tình tàn bạo khét tiếng, coi phụ nữ như súc vật đổi chác. Ba vị tông thất nữ trước đây do triều đình gả sang đó đều chết thảm chưa đầy nửa năm trong sự hành hạ tủi nhục.\n\nTriều đình trăm quan văn võ, mỗi năm ngốn hàng vạn hòm lương bổng bạc vàng của dân chúng, đến khi giặc cưỡi ngựa tràn qua ải thì sợ hãi run rẩy rụt cổ như rùa rúc trong mai. Bọn chúng không dám xuất binh quyết chiến, lại bày mưu hèn kế bẩn đẩy một đứa con gái vừa chịu tang cha ra làm vật tế thần để đổi lấy vài năm hòa bình giả tạo nhục nhã!\n\nViên nội quan họ Cao thấy tôi vẫn quỳ thẳng lưng bất động, hai mắt nhìn trừng trừng không chịu dập đầu tạ ơn, liền sẵng giọng nhắc nhở bằng thứ giọng điệu trịch thượng của kẻ cậy quyền thế:\n'Tần tiểu thư, thánh ân trời biển của hoàng thượng dành cho phủ Định Quốc Công đấy! Mau tiếp chỉ dập đầu tạ ơn đi chứ! Đừng để cả dòng họ Tần gia bị quan ngự sử dâng sớ ghép vào tội kháng chỉ khi quân, chu di tam tộc lúc nào không hay đâu!'.\n\nTôi từ từ ngẩng đầu lên. Mười năm theo cha lăn lộn nơi biên ải cát bụi mịt mù, từ năm mười hai tuổi tôi đã cưỡi ngựa bắn cung, nếm mật nằm gai nơi chiến hào, cùng các binh sĩ chia nhau từng bát cháo hoa hạt kê giữa mùa đông buốt giá. Trong huyết quản của đứa con gái họ Tần này chảy dòng máu sắt đá của tướng môn anh liệt chứ không phải thứ bùn nhão nơi khuê phòng để mặc cho đám quan lại kinh thành định đoạt số phận!\n\nTôi chống tay đứng dậy, bước từng bước vững chãi lại gần chiếc khay sơn son. Hai bàn tay tôi chai sạn vì nhiều năm cầm đao luyện kích đưa ra đón lấy cuốn thánh chỉ lạnh ngắt. Tôi nhìn thẳng vào đôi mắt trơ trẽn của viên nội quan, giọng nói trầm tĩnh nhưng uy lực vô cùng:\n'Cao công công về bẩm báo lại nguyên văn với hoàng thượng và Thừa tướng: Chiếu hòa thân này, Tần Uyển Dao tôi nhận! Vì giang sơn xã tắc, vì sự bình yên của bá tánh trăm họ, tôi sẵn sàng lên đường sang Bắc Địch! Nhưng đã là phụng mệnh vì quốc gia xuất giá, tôi có ba điều kiện sống còn. Nếu triều đình không chuẩn y bằng văn bản đóng dấu ngọc tỷ, Tần Uyển Dao này thà tự vẫn ngay trước cổng Ngọ Môn để máu nhuộm đỏ bậc thềm cấm thành, để thiên hạ đời đời khắc ghi nỗi nhục hèn nhát của triều đình!'.\n\nCao công công nghe xong giật nảy mình, sắc mặt tái mét, run giọng lắp bắp:\n'Cô... cô to gan lớn mật! Cô dám ra điều kiện mặc cả với hoàng thượng sao? Rốt cuộc cô muốn điều kiện gì?'.\n\nTôi bình thản giơ từng ngón tay lên, giọng đanh thép như tiếng chuông đồng vang vọng giữa sảnh đường:\n'Điều thứ nhất: Toàn bộ ba ngàn quân thiết kỵ Huyền Giáp do đích thân cha tôi gầy dựng ba mươi năm qua phải được sung làm quân hộ tống danh chính ngôn thuận theo tôi sang biên giới. Không một vị quan nào trong triều được phép giải tán, thu hồi quân trang hay điều chuyển một binh sĩ nào cho kẻ khác! Điều thứ hai: Lễ vật hòa thân của triều đình giao cho Bắc Địch không được dùng vàng bạc châu báu gấm vóc xa xỉ, mà phải chuyển toàn bộ giá trị thành năm vạn thạch lương khô, năm ngàn tấm vải bạt chống rét và ba vạn bao muối hạt thượng hạng. Điều thứ ba: Trao cho tôi lệnh bài Tiết độ sứ lâm thời toàn quyền vùng biên viễn. Kể từ lúc đoàn xe rời khỏi cổng kinh thành, sống chết thành bại, giao tranh hay nghị hòa nơi biên cương đều do một mình tôi tự quyết, không một kẻ nào được quyền can thiệp hay chỉ tay năm ngón!'.\n\nCao công công nghe xong toát mồ hôi hột ướt đẫm lưng áo. Lão vội vã ôm ống tay áo, lùi lũi leo lên cỗ xe ngựa chạy thục mạng về hoàng cung bẩm báo.\n\nĐám quan lại văn thần trong triều lúc bấy giờ đang run sợ trước vó ngựa của quân Bắc Địch ngoài cửa ải. Khi nghe tôi chỉ đòi ba ngàn tàn binh và số lương thực thô kệch chứ không đòi của cải vàng bạc, bọn chúng trong lòng mừng thầm, khẽ cười khẩy chê bai tôi là đứa con gái ngực lép đầu óc thiển cận không biết tính toán lợi ích bản thân. Chúng lập tức cùng nhau quỳ lạy dâng tấu xin hoàng đế phê chuẩn cả ba điều kiện ngay trong đêm để tống khứ tôi đi càng sớm càng tốt.\n\nBọn họ ngỡ rằng giao ba ngàn thiết kỵ cho một cô gái yếu đuối mang sang thảo nguyên chỉ là đưa thêm mồi ngon vào miệng cọp. Nhưng bọn quan lại chốn kinh thành chỉ biết ăn bổng lộc kia làm sao hiểu được giá trị vô giá của ba ngàn chiến sĩ kiên trung từng cùng cha tôi vào sinh ra tử? Đó là đội quân bách chiến bách thắng, kỷ luật thép, coi mệnh lệnh của họ Tần hơn cả mạng sống! Càng không một kẻ nào hiểu được rằng trong mùa đông khắc nghiệt nơi thảo nguyên tuyết trắng, muối hạt và lương khô mới là thứ vũ khí chí mạng định đoạt sự sống còn của cả một vương triều!\n\nBa ngày sau, tiếng kèn lệnh vang lên xé toang màn sương sớm, cánh cổng lớn của kinh thành từ từ mở toang. Không có kiệu hoa tám người khiêng lộng lẫy, không có phường nhạc công thổi kèn gõ trống mừng ngày vu quy của công chúa.\n\nTôi cởi bỏ tấm khăn tang trắng, khoác lên mình bộ giáp bạc lấp lánh do chính tay cha rèn cho ngày tôi tròn mười tám tuổi. Ngang hông, tôi thắt một dải lụa đỏ thắm tượng trưng cho hỷ sự hòa thân, sau lưng đeo cây cung thần chạm ngọc, tay nắm chặt ngọn trường thương thúc ngựa đi đầu đoàn quân xuất phát.\n\nPhía sau lưng tôi, ba ngàn chiến sĩ thiết kỵ Huyền Giáp cưỡi trên những con tuấn mã đen nhánh sừng sững như bức tường thành di động, ánh mắt mỗi người đều đằng đằng sát khí và rực cháy ý chí báo thù. Người dân kinh thành đứng kín hai bên đường, già trẻ lớn bé đều nín lặng rơi nước mắt, chắp tay cúi đầu tiễn đưa đứa con gái duy nhất của vị anh hùng dân tộc đã ngã xuống nơi sa trường.\n\nTôi ghìm cương ngựa, ngoái đầu nhìn lại kinh thành tráng lệ nguy nga lần cuối, khóe môi khẽ nhếch lên một nụ cười lạnh lùng trong gió bấc mùa đông. Chuyến đi này, Tần Uyển Dao tôi không đi để làm dâu, càng không đi để chịu nhục nhã cầu vinh! Tôi đi là để đòi lại từng giọt nợ máu cho cha tôi và mười vạn quân dân biên giới đã ngã xuống!"
    part2_full = "Sau hai mươi ngày ròng rã băng qua bão tuyết sa mạc, đoàn xe hòa thân của tôi dừng lại trước cổng thành bằng đá đen của vương đình Bắc Hãn. Đoàn xe hòa thân tiến vào vùng thảo nguyên biên giới sau hai mươi ngày ròng rã vượt qua muôn trùng bão tuyết. Gió đông nơi thảo nguyên rít từng hồi buốt nhói như xé rách da thịt, từng trận mưa tuyết trút xuống trắng xóa làm tuyết ngập đến tận bụng ngựa, bước chân hành quân vô cùng gian truân.\n\nTrại quân chính của Bắc Địch đóng cách biên ải năm mươi dặm về phía bắc, những túp lều bạt da thú trắng xóa trải dài ngút tầm mắt như một bầy sói đói đang nằm phục chờ mồi. Thủ lĩnh của chúng – Hãn vương Ô Lặc Đạt – sai đứa con trai thứ ba là A Sử Na dẫn theo năm ngàn kỵ binh tinh nhuệ nhất ra nghênh đón đoàn rước dâu nhằm phô trương uy thế và thị uy sức mạnh.\n\nA Sử Na cưỡi trên con tuấn mã lông hung đỏ hung hãn, thân hình hộ pháp lực lưỡng, khuôn mặt đầy râu quai nón bặm trợn. Hắn đưa đôi mắt ti hí quét nhìn đoàn xe, khi nhìn thấy tôi mặc chiến giáp bạc ngồi uy nghiêm trên lưng ngựa thay vì ngồi khóc lóc trong kiệu hoa, hắn liền ngửa cổ cười sằng sặc một tràng man rợ:\n'Ha ha ha! Lũ quan lại Nam triều nhát gan như chuột nhắt, nghe nói dâng cho phụ vương ta một nàng công chúa tuyệt sắc giai nhân, sao lại là một con nhãi ranh mặc giáp sắt thế này? Con nhãi kia, mau xuống ngựa quỳ mọp dưới chân ta dập đầu tạ tội, rồi mở hết các rương của hồi môn ra để bản hoàng tử kiểm tra! Nếu không có đủ mười hòm vàng ròng, hôm nay các ngươi đừng hòng sống sót bước vào lều phụ vương ta!'.\n\nĐám lính man tộc phía sau hắn đồng loạt hò reo man dại, huýt sáo inh ỏi, vung cao những lưỡi mã tấu sáng loáng định xông thẳng vào đoàn xe lương thực để cướp bóc.\n\nTôi không hề biến sắc, cánh tay phải khẽ nhấc lên giữa không trung. Ngay lập tức, ba ngàn kỵ binh thiết kỵ Huyền Giáp phía sau tôi đồng loạt rút kiếm khỏi vỏ!\n\nKeng! Keng! Keng!\n\nTiếng kim loại va chạm sắc lạnh vang rền cả một góc trời thảo nguyên. Ba ngàn mũi kích dài hạ xuống đồng loạt, tạo thành một bức tường thép gai góc và chết chóc, ánh mắt của từng chiến sĩ Huyền Giáp lạnh lẽo như lưỡi đao tẩm độc. Không khí giữa hai đoàn quân bỗng chốc đông cứng lại, nghẹt thở như trước một cơn cuồng phong bão táp.\n\nTôi nhìn thẳng vào mắt A Sử Na, giọng nói sang sảng vang xa át cả tiếng gió rít:\n'Ta là Chiêu Hòa Công chúa phụng chiếu chỉ của hoàng đế Nam triều sang liên hôn bang giao. Theo lễ nghi nghênh tiếp của hai quốc gia, chỉ có đích thân Hãn vương đứng tại vương trướng mới có đủ tư cách nhận của hồi môn và đàm đạo việc nước. Một tên hoàng tử thứ phẩm hạ đẳng như ngươi, dựa vào đâu mà dám đứng trước mặt ta múa may gươm giáo, buông lời vô lễ với công chúa thượng quốc?'.\n\nKhuôn mặt A Sử Na đỏ gay như gấc chín vì bị sỉ nhục trước mặt binh lính. Bàn tay hắn nắm chặt chuôi đao định rút ra liều mạng, nhưng khi nhìn thấy thế trận phòng thủ kín kẽ không một kẽ hở của quân Huyền Giáp, cùng khí thế ngút trời của những người lính từng chém gục biết bao dũng sĩ thảo nguyên, hắn đành nghiến răng ken két, hừ lạnh một tiếng rồi quay đầu ngựa dẫn đường đưa đoàn vào vương trướng.\n\nBên trong vương trướng rộng lớn sực nức mùi rượu sữa ngựa nồng nặc và mùi thịt nướng bốc khói. Hãn vương Ô Lặc Đạt ngồi chễm chệ trên chiếc ngai bọc da hổ trắng, thân hình to béo đồ sộ, đôi mắt ti hí đảo quanh thân hình tôi như loài kền kền đang rình mồi. Lão vuốt chòm râu xám, cười khà khà bằng thứ giọng ồm ồm giả lả:\n'Nàng công chúa nhỏ này gan dạ bản lĩnh lắm! Quả không hổ danh là con gái của Định Quốc Công Tần Chấn Thiên! Nhưng một khi nàng đã bước chân vào thảo nguyên này, nàng chỉ là một món đồ chơi trong trướng của ta mà thôi. Ta nghe thủ hạ bẩm báo, của hồi môn nàng mang sang chỉ toàn là muối hạt và lương khô thô kệch, không có lấy một hòm châu báu vàng bạc hay ngọc ngà gấm vóc. Nam triều các người coi thường thảo nguyên Bắc Địch ta đến thế sao?'.\n\nTôi bước lên phía trước ba bước, không quỳ lạy, tháo chiếc bao da bên hông lấy ra một tấm bản đồ địa lý thảo nguyên đặt thẳng lên bàn tiệc của lão:\n'Thưa Hãn vương, vàng bạc châu báu chốn kinh thành hoa lệ chỉ là thứ phù phiếm làm mờ mắt kẻ tham lam, không thể ăn no cũng không thể chống rét. Mùa đông năm nay bão tuyết tràn về sớm hơn mọi năm ba mươi ngày, tuyết dày ba thước chôn vùi toàn bộ đồng cỏ, đàn cừu và ngựa chiến của Bắc Địch chết cóng hàng vạn con ngoài bãi chăn thả. Nếu không có năm vạn thạch lương khô và ba vạn bao muối hạt của tôi mang sang cứu trợ, liệu một nửa số bộ lạc của Hãn vương có sống sót qua nổi tháng sau hay không?'.\n\nÔ Lặc Đạt giật mình đánh thót một cái, nụ cười trên mặt lão lập tức tắt ngấm. Từng lời tôi nói ra như mũi tên bắn trúng ngay tim đen và tử huyệt lớn nhất của Bắc Địch lúc bấy giờ. Mùa đông khắc nghiệt đang bóp nghẹt thảo nguyên, nạn đói khủng khiếp bắt đầu hoành hành dữ dội khắp các bộ tộc, đó chính là lý do thực sự khiến chúng phải xua quân gây chiến đòi hòa thân để cướp bóc lương thực cứu nguy cho mùa đông.\n\nLão già nheo mắt nhìn tôi đầy vẻ dè chừng và cảnh giác cao độ:\n'Vậy nàng muốn điều gì?'.\n\nTôi bình thản mỉm cười, ánh mắt kiên định tự tin:\n'Tôi muốn đích thân Hãn vương hạ lệnh đem toàn bộ số muối và lương thực này phân phát cứu đói cho các bộ lạc cơ hàn nhất ở bờ đông trước. Đổi lại, trong suốt ba tháng mùa đông giá rét này, quân đội Bắc Địch không được phép tiến sát biên giới Nam triều nửa bước. Và điều quan trọng nhất: Ba ngàn quân thiết kỵ Huyền Giáp của tôi sẽ đóng quân độc lập tại thung lũng Nhạn Môn Quan, tự canh gác, không chịu sự điều động của bất kỳ tướng lĩnh Bắc Địch nào!'.\n\nÔ Lặc Đạt tính toán một hồi lâu trong đầu. Thấy trước mắt có ngay số lương thực khổng lồ giải cứu các bộ lạc đang nổi loạn vì đói khát, lại nghĩ tôi chỉ là đứa con gái thân cô thế cô nơi đất khách quê người không thể làm nên trò trống gì, lão liền sảng khoái vỗ đùi đánh đét một cái, gật đầu chuẩn y toàn bộ đề nghị của tôi.\n\nLão già bạo tàn không thể ngờ được rằng, từng bao muối và bao lương khô mà tôi trực tiếp thân chinh đi phát cho các bộ lạc nghèo khó ở bờ đông đều kèm theo thông điệp nhân đạo cao cả của gia tộc họ Tần. Tôi cứu sống con cái họ khỏi cái chết đói, tôi băng bó vết thương cho những người già còm cõi. Chỉ trong vòng hai tháng ngắn ngủi, những người chăn cừu cơ hàn nơi thảo nguyên bờ đông đã coi tôi như một vị bồ tát cứu tinh mang lại sự sống cho gia đình họ giữa nạn đói kinh hoàng.\n\nTrong khi đó, tại thung lũng Nhạn Môn Quan hiểm trở, ba ngàn chiến sĩ thiết kỵ Huyền Giáp của tôi ngày đêm âm thầm huấn luyện trận địa hỏa công, chuẩn bị vũ khí và bí mật khảo sát cặn kẽ từng lối mòn hiểm yếu qua hẻm núi tuyết.\n\nMột kế hoạch phản kích long trời lở đất đã được tôi âm thầm bày binh bố trận, chỉ chờ ngọn gió đông chuyển hướng để thiêu rụi toàn bộ hang ổ của bầy sói hung tàn!"
    part3_full = "Đêm rằm tháng giêng tuyết rơi dày đặc phủ kín thung lũng biên cương, ngọn lửa hiệu từ đỉnh núi phía đông bất ngờ bùng lên báo hiệu thời khắc phản kích đã điểm. Đêm rằm tháng giêng, trời đổ tuyết lớn như trút nước, gió bão gầm thét dữ dội nơi thung lũng biên cương. Đúng như nguồn tin tình báo mật của các trinh sát bộ lạc bờ đông báo về cho tôi, tên hoàng tử thứ ba A Sử Na cùng một nhánh quân quý tộc hiếu chiến luôn bất mãn với thỏa ước hòa bình, đã âm thầm tập hợp một vạn kỵ binh thiết giáp tinh nhuệ nhất.\n\nLợi dụng đêm tối bão bùng, chúng lén lút men theo hẻm núi hiểm trở định tập kích bất ngờ cướp lại toàn bộ kho lương thảo tại Nhạn Môn Quan, sau đó tràn qua biên giới cướp bóc chém giết các làng mạc Nam triều để thỏa cơn thèm khát máu me.\n\nThế nhưng, khi toàn bộ một vạn quân kỵ của A Sử Na vừa lọt thỏm vào giữa lòng chảo thung lũng Nhạn Môn Quan, bốn bề vách núi bỗng chốc rực sáng như ban ngày bởi hàng ngàn bó đuốc bốc cháy hừng hực!\n\nTù... và... tiếng tù và đồng vang lên xé toang màn đêm tuyết giá!\n\nVút! Vút! Vút!\n\nHàng vạn mũi tên tẩm dầu hỏa từ trên đỉnh vách núi tuyết bắn xuống dồn dập như mưa rào mùa hạ. Những thùng dầu hỏa và bùi nhùi do quân tôi cài đặt sẵn dọc theo các sườn đèo đồng loạt bốc cháy ngùn ngụt, thiêu rụi toàn bộ lều bạt dã chiến và khóa chặt hoàn toàn con đường rút lui duy nhất của chúng.\n\nChưa dừng lại ở đó, tiếng nổ long trời lở đất vang lên từ đỉnh đèo khi các chiến sĩ công binh của tôi kích nổ các khối đá chặn dòng, khiến hàng ngàn tấn tuyết lở và đá tảng từ trên sườn núi ầm ầm đổ sập xuống lòng thung lũng, chôn vùi hơn nửa đội hình kỵ binh địch trong tiếng la hét kinh hoàng tuyệt vọng!\n\nTôi mặc bộ giáp bạc sáng chói lọi trong ánh lửa rực trời, tay cầm trường thương dũng mãnh thúc ngựa lao thẳng xuống lòng thung lũng. Phía sau tôi, ba ngàn thiết kỵ Huyền Giáp như những con rồng đen xé toang hàng ngũ đang hoảng loạn tột độ của quân Bắc Địch.\n\nThương hoa xoay vần như bão tuyết, tôi trực tiếp giao chiến với A Sử Na giữa vòng vây lửa. Chỉ sau ba mươi hiệp đấu kịch liệt, ngọn trường thương của tôi đã hất văng thanh đại đao trên tay hắn, mũi giáo sắc lạnh ghim chặt bả vai A Sử Na, ghim hắn nằm bẹp xuống nền tuyết trắng! Toàn bộ một vạn quân tập kích bị tiêu diệt và bắt sống hoàn toàn trong vòng chưa đầy một canh giờ!\n\nKhông để lỡ một giây phút vàng ngọc, ngay trong đêm bão tuyết bùng phát dữ dội, tôi hạ lệnh trói gô A Sử Na vắt ngang lưng ngựa, dẫn đầu toàn bộ đội quân thần tốc tiến thẳng về phía vương trướng của Hãn vương Ô Lặc Đạt.\n\nCác bộ tộc chăn cừu ở bờ đông từng chịu ơn cứu mạng của tôi đã đồng loạt mở toang các cánh cổng doanh trại, họ dẫn đường cho đoàn quân của tôi vượt qua các bãi mìn chông tuyết. Không một người lính chăn cừu nào chịu rút đao cầm cung để bảo vệ cho tên Hãn vương bạo tàn độc ác nữa!\n\nRầm!\n\nCánh cửa vương trướng bị ngọn trường thương của tôi đạp tung ra thành từng mảnh vụn. Hãn vương Ô Lặc Đạt đang ôm ấp đám tỳ thiếp trong cơn say túy lúy bàng hoàng bật dậy. Khi nhìn thấy đứa con trai cưng bị ném xuống đất đầy máu me, và lưỡi trường thương lạnh buốt của tôi đã kề sát yết hầu ngay trên chiếc ngai da hổ, lão già sợ hãi đến mức hai hàm răng va vào nhau lập cập, ngã quỵ xuống đất như một con chó rách:\n'Tần... Tần Uyển Dao! Nàng... nàng là ma quỷ phương nào phái đến? Nàng đã lừa gạt lòng tin của ta!'.\n\nTôi cúi nhìn lão già bằng ánh mắt sắc lẹm, từng lời thốt ra đanh thép vang vọng khắp đại trướng:\n'Ta không phải ma quỷ! Ta là con gái của Định Quốc Công Tần Chấn Thiên! Năm xưa cha ta nhân từ tha mạng cho ngươi nơi ải Bắc, ngươi lại nhân lúc ông ấy kiệt sức mà xua quân đánh lén hại chết cha ta. Hôm nay, Tần Uyển Dao này lấy thủ cấp của ngươi để tế vong linh cha ta và mười vạn anh linh chiến sĩ đã ngã xuống bảo vệ biên cương!'.\n\nXoẹt!\n\nMột đường kiếm bạc lóe lên giữa không trung, thủ cấp của kẻ bạo chúa Ô Lặc Đạt lăn lông lốc xuống sàn tiệc, chấm dứt hoàn toàn ba mươi năm tội ác và máu lửa nơi biên thùy.\n\nNgay tại vương trướng đêm đó, tôi giơ cao tấm lệnh bài Tiết độ sứ, lập một vị thủ lĩnh đức độ và yêu chuộng hòa bình của các bộ tộc bờ đông lên làm Hãn vương mới. Trước sự chứng kiến của các tù trưởng thảo nguyên, một bản hiệp ước hòa bình vĩnh viễn đã được ký kết: Bắc Địch đời đời thần phục Nam triều, cống nạp chiến mã hàng năm, và mở rộng các phiên chợ biên mậu để người dân hai bên cùng nhau làm ăn sinh sống trong cảnh thái bình thịnh trị.\n\nMột tháng sau, tin thắng trận chấn động kinh hoàng như một cơn địa chấn truyền thẳng về kinh đô hoa lệ.\n\nToàn bộ triều đình Nam quốc bàng hoàng ngơ ngác không dám tin vào tai mình. Bản tấu sớ báo tin thắng trận kèm theo thủ cấp của Ô Lặc Đạt và bức hàng thư của tân Hãn vương được phi ngựa hỏa tốc đưa vào tận điện Kim Loan.\n\nTên thừa tướng gian xảo và đám quan văn từng lớn tiếng ép tôi đi hòa thân mặt cắt không còn một giọt máu, quỳ run lẩy bẩy dập đầu xin tha tội trước ngai vàng của hoàng đế.\n\nĐoàng! Đoàng! Tiếng pháo lệnh khải hoàn vang rền từ ngoài cổng kinh thành. Cả trăm ngàn bá tánh kinh đô ùa ra đường hò reo mừng rỡ, cờ hoa đỏ rợp cả một góc trời mùa xuân ấm áp.\n\nGiữa đoàn quân thiết kỵ Huyền Giáp oai phong lẫm liệt, tôi cưỡi trên con chiến mã dũng mãnh, ngẩng cao đầu đón những tia nắng ấm áp đầu tiên của mùa xuân rọi xuống vai áo giáp.\n\nChiếc chiếu hòa thân nhục nhã ngày nào đã bị vó ngựa của tôi san phẳng thành chiến công hiển hách lẫy lừng thiên cổ. Hoàng đế đích thân ban thưởng vạn lượng hoàng kim, sắc phong tôi làm Nữ Đại Tướng Quân thống lĩnh toàn bộ mười vạn quân biên phòng phía bắc, nắm giữ ấn soái tối cao của triều đình.\n\nTôi mỉm cười đặt tay lên chuôi kiếm, phóng tầm mắt nhìn về phía chân trời xa xôi nơi biên ải thanh bình. Từ nay về sau, trên mảnh đất này, sẽ không một kẻ hèn nhát nào còn dám đem danh dự và số phận của những người phụ nữ ra làm vật đổi chác hòa bình nữa!"
